import readline from 'node:readline';

import { UsageError } from '../errors.js';
import { color, isInteractive, symbols } from '../ui/theme.js';

import type { SetupAgent, SetupScope } from './agents.js';

export class PromptCancelledError extends Error {
  constructor(readonly exitCode: number = 0) {
    super('Setup cancelled.');
    this.name = 'PromptCancelledError';
  }
}

export interface AgentChoice {
  detected: boolean;
  displayName: string;
  name: SetupAgent;
}

interface ScopeChoice {
  hint: string;
  label: string;
  value: SetupScope;
}

const SCOPE_CHOICES: ScopeChoice[] = [
  { hint: 'the detected repository root', label: 'Project', value: 'project' },
  {
    hint: 'every project (~/.cursor, ~/.codex, …)',
    label: 'Global',
    value: 'global',
  },
];

export function parseScopeSelection(raw: string): SetupScope {
  const normalized = raw.trim().toLowerCase();

  if (
    normalized === '' ||
    normalized === '1' ||
    normalized === 'p' ||
    normalized === 'project'
  ) {
    return 'project';
  }

  if (normalized === '2' || normalized === 'g' || normalized === 'global') {
    return 'global';
  }

  throw new UsageError(
    `Unknown scope: "${raw.trim()}". Choose "project" or "global".`
  );
}

export function promptScope(): Promise<SetupScope> {
  if (isInteractive()) {
    return promptScopeInteractive();
  }

  return promptScopeByLine();
}

function promptScopeInteractive(): Promise<SetupScope> {
  const input = process.stdin;
  const output = process.stderr;
  const wasRaw = input.isRaw === true;
  let cursor = 0;
  let renderedLines = 0;

  try {
    input.setRawMode(true);
  } catch {
    return promptScopeByLine();
  }
  readline.emitKeypressEvents(input);

  return new Promise<SetupScope>((resolve, reject) => {
    function render(): void {
      if (renderedLines > 0) {
        output.write(`\u001B[${renderedLines}A`);
      }

      const lines = [
        `${color.magenta(symbols.diamond)} ${color.bold('Where should DocSearch be installed?')} ${color.dim('(↑↓ move · enter confirm)')}`,
        ...SCOPE_CHOICES.map((choice, index) => {
          const active = index === cursor;
          const radio = active
            ? color.green(symbols.checkboxOn)
            : color.dim(symbols.checkboxOff);
          const pointer = active ? color.cyan(symbols.pointer) : ' ';
          const label = active ? color.cyan(choice.label) : choice.label;
          return `${pointer} ${radio} ${label} ${color.dim(`— ${choice.hint}`)}`;
        }),
      ];

      output.write(`${lines.map((line) => `\u001B[K${line}`).join('\n')}\n`);
      renderedLines = lines.length;
    }

    function cleanup(): void {
      input.setRawMode(wasRaw);
      input.removeListener('keypress', onKeypress);
      output.write('\u001B[?25h');
      input.pause();
    }

    function onKeypress(_input: string, key: readline.Key | undefined): void {
      if (!key) {
        return;
      }

      if (key.name === 'up' || key.name === 'k') {
        cursor = (cursor - 1 + SCOPE_CHOICES.length) % SCOPE_CHOICES.length;
        render();
      } else if (key.name === 'down' || key.name === 'j') {
        cursor = (cursor + 1) % SCOPE_CHOICES.length;
        render();
      } else if (key.name === 'return') {
        cleanup();
        resolve(SCOPE_CHOICES[cursor].value);
      } else if (
        key.name === 'escape' ||
        (key.ctrl === true && key.name === 'c')
      ) {
        cleanup();
        output.write('\n');
        reject(new PromptCancelledError(key.ctrl === true ? 130 : 0));
      }
    }

    output.write('\u001B[?25l');
    input.on('keypress', onKeypress);
    input.resume();
    render();
  });
}

async function promptScopeByLine(): Promise<SetupScope> {
  const output = process.stderr;

  output.write(
    `${color.magenta(symbols.diamond)} ${color.bold('Where should DocSearch be installed?')}\n`
  );
  for (const [index, choice] of SCOPE_CHOICES.entries()) {
    output.write(
      `  ${color.cyan(String(index + 1))}. ${choice.label} ${color.dim(`— ${choice.hint}`)}\n`
    );
  }
  output.write(
    `${color.dim('Enter "project" or "global" (blank for project):')} `
  );

  return parseScopeSelection(await readSingleLine());
}

export function parseAgentSelection(
  raw: string,
  choices: AgentChoice[]
): SetupAgent[] {
  const normalized = raw.trim().toLowerCase();

  if (normalized === '') {
    return choices
      .filter((choice) => choice.detected)
      .map((choice) => choice.name);
  }

  if (normalized === 'all' || normalized === '*') {
    return choices.map((choice) => choice.name);
  }

  if (normalized === 'none') {
    return [];
  }

  const selected = new Set<SetupAgent>();

  for (const token of normalized.split(/[\s,]+/).filter(Boolean)) {
    const index = Number(token);
    if (Number.isInteger(index) && index >= 1 && index <= choices.length) {
      selected.add(choices[index - 1].name);
    } else {
      const match = choices.find((choice) => choice.name === token);
      if (!match) {
        throw new UsageError(
          `Unknown agent: "${token}". Choose a number or one of: ${choices.map((c) => c.name).join(', ')}.`
        );
      }
      selected.add(match.name);
    }
  }

  return [...selected];
}

export function promptAgents(choices: AgentChoice[]): Promise<SetupAgent[]> {
  if (isInteractive()) {
    return promptAgentsInteractive(choices);
  }

  return promptAgentsByLine(choices);
}

function promptAgentsInteractive(
  choices: AgentChoice[]
): Promise<SetupAgent[]> {
  const input = process.stdin;
  const output = process.stderr;
  const wasRaw = input.isRaw === true;
  const selected = choices.map((choice) => choice.detected);
  let cursor = 0;
  let renderedLines = 0;

  try {
    input.setRawMode(true);
  } catch {
    return promptAgentsByLine(choices);
  }
  readline.emitKeypressEvents(input);

  return new Promise<SetupAgent[]>((resolve, reject) => {
    function render(): void {
      if (renderedLines > 0) {
        output.write(`\u001B[${renderedLines}A`);
      }

      const lines = [
        `${color.magenta(symbols.diamond)} ${color.bold('Select agents to configure')} ${color.dim('(↑↓ move · space toggle · a all · enter confirm)')}`,
        ...choices.map((choice, index) => {
          const box = selected[index]
            ? color.green(symbols.checkboxOn)
            : color.dim(symbols.checkboxOff);
          const pointer = index === cursor ? color.cyan(symbols.pointer) : ' ';
          const name =
            index === cursor
              ? color.cyan(choice.displayName)
              : choice.displayName;
          const detected = choice.detected ? color.dim(' (detected)') : '';
          return `${pointer} ${box} ${name}${detected}`;
        }),
      ];

      output.write(`${lines.map((line) => `\u001B[K${line}`).join('\n')}\n`);
      renderedLines = lines.length;
    }

    function cleanup(): void {
      input.setRawMode(wasRaw);
      input.removeListener('keypress', onKeypress);
      output.write('\u001B[?25h');
      input.pause();
    }

    function onKeypress(_input: string, key: readline.Key | undefined): void {
      if (!key) {
        return;
      }

      if (key.name === 'up' || key.name === 'k') {
        cursor = (cursor - 1 + choices.length) % choices.length;
        render();
      } else if (key.name === 'down' || key.name === 'j') {
        cursor = (cursor + 1) % choices.length;
        render();
      } else if (key.name === 'space') {
        selected[cursor] = !selected[cursor];
        render();
      } else if (key.name === 'a') {
        const allSelected = selected.every(Boolean);
        selected.fill(!allSelected);
        render();
      } else if (key.name === 'return') {
        cleanup();
        resolve(
          choices
            .filter((_, index) => selected[index])
            .map((choice) => choice.name)
        );
      } else if (
        key.name === 'escape' ||
        (key.ctrl === true && key.name === 'c')
      ) {
        cleanup();
        output.write('\n');
        reject(new PromptCancelledError(key.ctrl === true ? 130 : 0));
      }
    }

    output.write('\u001B[?25l');
    input.on('keypress', onKeypress);
    input.resume();
    render();
  });
}

async function promptAgentsByLine(
  choices: AgentChoice[]
): Promise<SetupAgent[]> {
  const output = process.stderr;

  output.write(
    `${color.magenta(symbols.diamond)} ${color.bold('Select agents to configure')}\n`
  );
  for (const [index, choice] of choices.entries()) {
    const detected = choice.detected ? color.dim(' (detected)') : '';
    output.write(
      `  ${color.cyan(String(index + 1))}. ${choice.displayName}${detected}\n`
    );
  }
  output.write(
    `${color.dim('Enter numbers/names (comma-separated), "all", or blank for detected:')} `
  );

  const raw = await readSingleLine();
  return parseAgentSelection(raw, choices);
}

// A single persistent line reader shared across prompts. Reading one line at a
// time with fresh listeners loses buffered input between prompts (and can hang
// at EOF), so we buffer stdin once and hand out lines on demand.
let stdinBuffer = '';
let stdinInitialized = false;
let stdinEnded = false;
const lineResolvers: Array<(line: string) => void> = [];

function pumpLines(): void {
  while (lineResolvers.length > 0) {
    const newline = stdinBuffer.indexOf('\n');
    if (newline >= 0) {
      const line = stdinBuffer.slice(0, newline).replace(/\r$/, '');
      stdinBuffer = stdinBuffer.slice(newline + 1);
      lineResolvers.shift()?.(line);
    } else if (stdinEnded) {
      const line = stdinBuffer;
      stdinBuffer = '';
      lineResolvers.shift()?.(line);
    } else {
      break;
    }
  }

  if (lineResolvers.length === 0 && !stdinEnded) {
    process.stdin.pause();
  }
}

function initStdin(): void {
  if (stdinInitialized) {
    return;
  }

  stdinInitialized = true;
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk: string) => {
    stdinBuffer += chunk;
    pumpLines();
  });
  process.stdin.on('end', () => {
    stdinEnded = true;
    pumpLines();
  });
}

function readSingleLine(): Promise<string> {
  initStdin();

  return new Promise((resolve) => {
    lineResolvers.push(resolve);
    process.stdin.resume();
    pumpLines();
  });
}

/* eslint-disable import/no-unresolved -- NodeNext source imports use runtime .js extensions. */
import { homedir } from 'node:os';
import { dirname, isAbsolute, join, relative, resolve } from 'node:path';

import { DOCSEARCH_MCP_SERVER_NAME } from '../constants.js';

import {
  getAgent,
  getAllAgents,
  type AgentConfig,
  type PathContext,
  type SetupAgent,
  type SetupScope,
} from './agents.js';
import type { AgentChoice } from './prompt.js';
import { getRuleContent, getSkillContent } from './templates.js';
import {
  appendRuleSection,
  appendTomlServer,
  pathExists,
  resolveConfigPath,
  upsertJsonServerEntry,
  writeRuleFile,
  writeSkill,
} from './writers.js';

export interface SetupOptions {
  agents: SetupAgent[];
  cwd?: string;
  endpoint: string;
  env?: NodeJS.ProcessEnv;
  homeDir?: string;
  scope: SetupScope;
}

export interface SetupResult {
  agent: string;
  mcpPath: string;
  mcpStatus: string;
  rulePath: string;
  ruleStatus: string;
  skillPath: string;
  skillStatus: string;
}

export function createPathContext(
  overrides: Partial<PathContext> = {}
): PathContext {
  return {
    cwd: overrides.cwd ?? process.cwd(),
    env: overrides.env ?? process.env,
    homeDir: overrides.homeDir ?? homedir(),
  };
}

// Version control roots are the canonical project root: they match how Cursor,
// Claude Code, Codex, etc. resolve project config (from the repo/workspace top).
const VCS_MARKERS = ['.git', '.hg', '.svn'];

// Markers that only exist at the true repo root, so they beat a nested
// package.json when locating a monorepo root without VCS metadata.
const ROOT_MARKERS = [
  'pnpm-workspace.yaml',
  'bun.lock',
  'bun.lockb',
  'pnpm-lock.yaml',
  'package-lock.json',
  'yarn.lock',
  'go.work',
  'deno.json',
  'deno.jsonc',
  'turbo.json',
  'nx.json',
  'lerna.json',
];

// Walks up from `startDir` (never crossing `homeDir` or the filesystem root)
// and returns the best project root. Falls back to `startDir` when nothing is
// found, so a directory-less invocation still installs into the current folder.
export async function findProjectRoot(
  startDir: string,
  homeDir: string
): Promise<string> {
  const start = resolve(startDir);
  const home = resolve(homeDir);
  const stopBeforeHome = start !== home && isPathWithin(start, home);
  let vcsRoot: string | undefined;
  let rootMarkerDir: string | undefined;
  let topmostPackage: string | undefined;

  let dir = start;
  let reachedFileSystemRoot = false;
  while (!reachedFileSystemRoot) {
    if (stopBeforeHome && dir === home) {
      break;
    }
    if (vcsRoot === undefined && (await hasAnyMarker(dir, VCS_MARKERS))) {
      vcsRoot = dir;
    }
    if (
      rootMarkerDir === undefined &&
      (await hasAnyMarker(dir, ROOT_MARKERS))
    ) {
      rootMarkerDir = dir;
    }
    if (await pathExists(join(dir, 'package.json'))) {
      topmostPackage = dir;
    }

    const parent = dirname(dir);
    reachedFileSystemRoot = parent === dir;
    dir = parent;
  }

  return vcsRoot ?? rootMarkerDir ?? topmostPackage ?? start;
}

async function hasAnyMarker(dir: string, markers: string[]): Promise<boolean> {
  const found = await Promise.all(
    markers.map((marker) => pathExists(join(dir, marker)))
  );
  return found.some(Boolean);
}

function isPathWithin(path: string, parent: string): boolean {
  const pathFromParent = relative(parent, path);
  return (
    pathFromParent !== '..' &&
    !pathFromParent.startsWith(
      `..${process.platform === 'win32' ? '\\' : '/'}`
    ) &&
    !isAbsolute(pathFromParent)
  );
}

export async function setupDocSearch(
  options: SetupOptions
): Promise<SetupResult[]> {
  const context = createPathContext({
    cwd: options.cwd,
    env: options.env,
    homeDir: options.homeDir,
  });
  const results: SetupResult[] = [];

  for (const agentName of options.agents) {
    results.push(
      await setupAgent(getAgent(agentName, context), {
        endpoint: options.endpoint,
        scope: options.scope,
      })
    );
  }

  return results;
}

export async function detectAgents(
  scope: SetupScope,
  context: PathContext
): Promise<SetupAgent[]> {
  const detected: SetupAgent[] = [];
  const allAgents = getAllAgents(context);

  for (const agent of Object.values(allAgents)) {
    const paths =
      scope === 'global' ? agent.detect.globalPaths : agent.detect.projectPaths;
    for (const path of paths) {
      if (await pathExists(path)) {
        detected.push(agent.name);
        break;
      }
    }
  }

  return detected;
}

export function buildAgentChoices(
  context: PathContext,
  detected: SetupAgent[]
): AgentChoice[] {
  const detectedSet = new Set(detected);

  return Object.values(getAllAgents(context)).map((agent) => ({
    detected: detectedSet.has(agent.name),
    displayName: agent.displayName,
    name: agent.name,
  }));
}

async function setupAgent(
  agent: AgentConfig,
  options: { endpoint: string; scope: SetupScope }
): Promise<SetupResult> {
  const mcpPath = await installMcpConfig(
    agent,
    options.endpoint,
    options.scope
  );
  const rulePath = await installRule(agent, options.scope);
  const skill = await writeSkill(
    agent.skill.dir(options.scope),
    getSkillContent()
  );

  return {
    agent: agent.displayName,
    mcpPath: mcpPath.path,
    mcpStatus: mcpPath.alreadyExists ? 'updated' : 'configured',
    rulePath: rulePath.path,
    ruleStatus: rulePath.status,
    skillPath: skill.path,
    skillStatus: skill.alreadyExists ? 'preserved' : 'installed',
  };
}

async function installMcpConfig(
  agent: AgentConfig,
  endpoint: string,
  scope: SetupScope
): Promise<{ alreadyExists: boolean; path: string }> {
  const candidates =
    scope === 'global' ? agent.mcp.globalPaths : agent.mcp.projectPaths;
  const mcpPath = await resolveConfigPath(candidates);
  const entry = agent.mcp.buildEntry(endpoint);

  if (mcpPath.endsWith('.toml')) {
    const result = await appendTomlServer(mcpPath, entry);
    return { alreadyExists: result.alreadyExists, path: mcpPath };
  }

  const result = await upsertJsonServerEntry(
    mcpPath,
    agent.mcp.configKey,
    entry
  );
  return { alreadyExists: result.alreadyExists, path: mcpPath };
}

async function installRule(
  agent: AgentConfig,
  scope: SetupScope
): Promise<{ path: string; status: string }> {
  const content = getRuleContent(agent.name);

  if (agent.rule.kind === 'file') {
    const rulePath = join(agent.rule.dir(scope), agent.rule.filename);
    const result = await writeRuleFile(rulePath, content);
    return {
      path: rulePath,
      status: result.alreadyExists ? 'preserved' : 'installed',
    };
  }

  const rulePath = agent.rule.file(scope);
  const existed = await pathExists(rulePath);
  await appendRuleSection(rulePath, content);
  return { path: rulePath, status: existed ? 'updated' : 'installed' };
}

export { DOCSEARCH_MCP_SERVER_NAME };

/* eslint-disable import/no-unresolved -- NodeNext source imports use runtime .js extensions. */
import {
  access,
  mkdir,
  readFile,
  realpath,
  rename,
  rm,
  stat,
  writeFile,
} from 'node:fs/promises';
import { dirname, join } from 'node:path';

import {
  applyEdits,
  modify,
  parse,
  printParseErrorCode,
  type FormattingOptions,
  type ParseError,
} from 'jsonc-parser';

import { DOCSEARCH_MCP_SERVER_NAME } from '../constants.js';
import { UsageError } from '../errors.js';

const SECTION_START = '<!-- algolia-docsearch:start -->';
const SECTION_END = '<!-- algolia-docsearch:end -->';

export async function pathExists(path: string): Promise<boolean> {
  try {
    await access(path);
    return true;
  } catch (error) {
    if (isMissingFileError(error)) {
      return false;
    }
    throw error;
  }
}

export async function resolveConfigPath(candidates: string[]): Promise<string> {
  for (const candidate of candidates) {
    if (await pathExists(candidate)) {
      return candidate;
    }
  }

  return candidates[0];
}

export async function upsertJsonServerEntry(
  filePath: string,
  configKey: string,
  entry: Record<string, unknown>
): Promise<{ alreadyExists: boolean }> {
  const existing = await readTextFile(filePath);
  const source = existing.trim() === '' ? '{}\n' : existing;
  const errors: ParseError[] = [];
  const parsed = parse(source, errors, {
    allowTrailingComma: true,
    disallowComments: false,
  }) as unknown;

  if (errors.length > 0) {
    const firstError = errors[0];
    throw new UsageError(
      `Cannot update ${filePath}: invalid JSON/JSONC (${printParseErrorCode(firstError.error)} at offset ${firstError.offset}).`
    );
  }
  if (!isPlainObject(parsed)) {
    throw new UsageError(
      `Cannot update ${filePath}: the configuration root must be an object.`
    );
  }

  const section = parsed[configKey];
  if (section !== undefined && !isPlainObject(section)) {
    throw new UsageError(
      `Cannot update ${filePath}: "${configKey}" must be an object.`
    );
  }

  const serverEntry = section?.[DOCSEARCH_MCP_SERVER_NAME];
  if (serverEntry !== undefined && !isPlainObject(serverEntry)) {
    throw new UsageError(
      `Cannot update ${filePath}: "${configKey}.${DOCSEARCH_MCP_SERVER_NAME}" must be an object.`
    );
  }

  const alreadyExists = serverEntry !== undefined;
  const mergedEntry = {
    ...serverEntry,
    ...entry,
  };
  const edits = modify(
    source,
    [configKey, DOCSEARCH_MCP_SERVER_NAME],
    mergedEntry,
    {
      formattingOptions: inferFormatting(source),
    }
  );
  const updated = ensureFinalNewline(applyEdits(source, edits));

  await writeFileAtomic(filePath, updated);
  return { alreadyExists };
}

export function buildTomlServerBlock(entry: Record<string, unknown>): string {
  return [
    `[mcp_servers.${DOCSEARCH_MCP_SERVER_NAME}]`,
    ...Object.entries(entry).map(
      ([key, value]) => `${key} = ${JSON.stringify(value)}`
    ),
    '',
  ].join('\n');
}

export async function appendTomlServer(
  filePath: string,
  entry: Record<string, unknown>
): Promise<{ alreadyExists: boolean }> {
  const existing = await readTextFile(filePath);
  const block = buildTomlServerBlock(entry);
  const sectionHeader = `[mcp_servers.${DOCSEARCH_MCP_SERVER_NAME}]`;
  const headerRegex = new RegExp(
    `^${escapeRegExp(sectionHeader)}[ \\t]*$`,
    'gm'
  );
  const matches = [...existing.matchAll(headerRegex)];
  if (matches.length > 1) {
    throw new UsageError(
      `Cannot update ${filePath}: duplicate ${sectionHeader} sections.`
    );
  }

  const alreadyExists = matches.length === 1;
  const content = alreadyExists
    ? mergeTomlSection(existing, matches[0], entry, filePath)
    : appendBlock(existing, block);

  await writeFileAtomic(filePath, content);
  return { alreadyExists };
}

export async function writeRuleFile(
  filePath: string,
  content: string
): Promise<{ alreadyExists: boolean }> {
  const alreadyExists = await pathExists(filePath);
  if (!alreadyExists) {
    await writeFileAtomic(filePath, content);
  }
  return { alreadyExists };
}

export async function appendRuleSection(
  filePath: string,
  content: string
): Promise<void> {
  const existing = await readTextFile(filePath);
  const hasStart = existing.includes(SECTION_START);
  const hasEnd = existing.includes(SECTION_END);
  if (hasStart !== hasEnd) {
    throw new UsageError(
      `Cannot update ${filePath}: incomplete DocSearch managed section.`
    );
  }

  const section = `${SECTION_START}\n${content.trim()}\n${SECTION_END}`;
  const updated =
    hasStart && hasEnd
      ? existing.replace(
          new RegExp(
            `${escapeRegExp(SECTION_START)}[\\s\\S]*?${escapeRegExp(SECTION_END)}`
          ),
          section
        )
      : appendBlock(existing, `${section}\n`);

  await writeFileAtomic(filePath, updated);
}

export async function writeSkill(
  skillDir: string,
  content: string
): Promise<{ alreadyExists: boolean; path: string }> {
  const skillPath = join(skillDir, DOCSEARCH_MCP_SERVER_NAME, 'SKILL.md');
  const alreadyExists = await pathExists(skillPath);
  if (!alreadyExists) {
    await writeFileAtomic(skillPath, content);
  }
  return { alreadyExists, path: skillPath };
}

function mergeTomlSection(
  existing: string,
  headerMatch: RegExpMatchArray,
  entry: Record<string, unknown>,
  filePath: string
): string {
  const startIdx = headerMatch.index;
  if (startIdx === undefined) {
    throw new UsageError(
      `Cannot update ${filePath}: failed to locate the DocSearch MCP section.`
    );
  }

  const lineBreak = existing.includes('\r\n') ? '\r\n' : '\n';
  const headerEnd = startIdx + headerMatch[0].length;
  const rest = existing.slice(headerEnd);
  const nextHeader = /^[ \t]*\[[^\]\r\n]+\][ \t]*(?:#.*)?$/m.exec(rest);
  const endIdx =
    nextHeader?.index === undefined
      ? existing.length
      : headerEnd + nextHeader.index;
  const lines = existing
    .slice(startIdx, endIdx)
    .replace(/\s+$/, '')
    .split(/\r?\n/);

  for (const [key, value] of Object.entries(entry)) {
    const keyRegex = new RegExp(`^(\\s*)${escapeRegExp(key)}\\s*=`);
    const matchingLines = lines
      .map((line, index) => ({ index, match: keyRegex.exec(line) }))
      .filter((candidate) => candidate.match !== null);

    if (matchingLines.length > 1) {
      throw new UsageError(
        `Cannot update ${filePath}: duplicate "${key}" values in the DocSearch MCP section.`
      );
    }

    const replacement = `${key} = ${toTomlValue(value, filePath)}`;
    const matchingLine = matchingLines[0];
    if (matchingLine?.match) {
      const comment = readTomlInlineComment(lines[matchingLine.index]);
      lines[matchingLine.index] =
        `${matchingLine.match[1]}${replacement}${comment}`;
    } else {
      lines.push(replacement);
    }
  }

  const mergedSection = `${lines.join(lineBreak)}${lineBreak}`;
  return ensureFinalNewline(
    `${existing.slice(0, startIdx)}${mergedSection}${existing.slice(endIdx)}`
  );
}

function toTomlValue(value: unknown, filePath: string): string {
  if (
    typeof value === 'string' ||
    typeof value === 'boolean' ||
    typeof value === 'number'
  ) {
    return JSON.stringify(value);
  }

  throw new UsageError(
    `Cannot update ${filePath}: unsupported TOML value in the DocSearch MCP configuration.`
  );
}

function readTomlInlineComment(line: string): string {
  let quote: '"' | "'" | undefined;
  let escaped = false;

  for (let index = 0; index < line.length; index++) {
    const character = line[index];
    if (escaped) {
      escaped = false;
    } else if (quote === '"' && character === '\\') {
      escaped = true;
    } else if (quote && character === quote) {
      quote = undefined;
    } else if (!quote && (character === '"' || character === "'")) {
      quote = character;
    } else if (!quote && character === '#') {
      const whitespace = line.slice(0, index).match(/[ \t]*$/)?.[0] ?? '';
      return `${whitespace || ' '}${line.slice(index)}`;
    }
  }

  return '';
}

function appendBlock(existing: string, block: string): string {
  const lineBreak = existing.includes('\r\n') ? '\r\n' : '\n';
  const normalizedBlock = block.replace(/\r?\n/g, lineBreak);
  if (!existing) {
    return normalizedBlock.endsWith(lineBreak)
      ? normalizedBlock
      : `${normalizedBlock}${lineBreak}`;
  }

  const separator = existing.endsWith(lineBreak)
    ? lineBreak
    : `${lineBreak}${lineBreak}`;
  return `${existing}${separator}${
    normalizedBlock.endsWith(lineBreak)
      ? normalizedBlock
      : `${normalizedBlock}${lineBreak}`
  }`;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function inferFormatting(source: string): FormattingOptions {
  const lineBreak = source.includes('\r\n') ? '\r\n' : '\n';
  const indentation = source.match(/^[ \t]+(?=")/m)?.[0];
  const insertSpaces = indentation?.includes('\t') !== true;

  return {
    eol: lineBreak,
    insertSpaces,
    tabSize: insertSpaces ? (indentation?.length ?? 2) : 1,
  };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function ensureFinalNewline(content: string): string {
  if (content.endsWith('\n')) {
    return content;
  }
  return `${content}\n`;
}

async function readTextFile(filePath: string): Promise<string> {
  try {
    return await readFile(filePath, 'utf-8');
  } catch (error) {
    if (isMissingFileError(error)) {
      return '';
    }
    throw error;
  }
}

async function writeFileAtomic(
  filePath: string,
  content: string
): Promise<void> {
  const targetPath = await resolveExistingPath(filePath);
  await mkdir(dirname(targetPath), { recursive: true });

  let mode: number | undefined;
  try {
    mode = (await stat(targetPath)).mode % 0o1000;
  } catch (error) {
    if (!isMissingFileError(error)) {
      throw error;
    }
  }

  const tempPath = `${targetPath}.${process.pid}.${Date.now()}.tmp`;
  try {
    await writeFile(tempPath, content, {
      encoding: 'utf-8',
      mode,
    });
    await rename(tempPath, targetPath);
  } finally {
    await rm(tempPath, { force: true });
  }
}

async function resolveExistingPath(filePath: string): Promise<string> {
  try {
    return await realpath(filePath);
  } catch (error) {
    if (isMissingFileError(error)) {
      return filePath;
    }
    throw error;
  }
}

function isMissingFileError(error: unknown): error is NodeJS.ErrnoException {
  return error instanceof Error && 'code' in error && error.code === 'ENOENT';
}

import React, { type JSX, useEffect, useState } from 'react';

import { LoadingIcon } from '../icons';
import type { StoredSearchPlugin } from '../stored-searches';
import type {
  AskAiFeedbackReason,
  OnAskAiFeedback,
  StoredAskAiState,
} from '../types';

export type FeedbackActionsTranslations = Partial<{
  /**
   * Tooltip/aria-label for the button that copies the assistant's answer to the
   * clipboard.
   */
  copyButtonTitle: string;
  /**
   * Transient confirmation label shown on the copy button right after a
   * successful copy.
   */
  copyButtonCopiedText: string;
  /** Tooltip/aria-label for the thumbs-up (positive feedback) button. */
  likeButtonTitle: string;
  /**
   * Tooltip/aria-label for the thumbs-down (negative feedback) button that
   * opens the notes form.
   */
  dislikeButtonTitle: string;
  /** Confirmation message shown after feedback has been submitted. */
  thanksForFeedbackText: string;
  /**
   * Heading displayed at the top of the negative feedback form (e.g. "What went
   * wrong?").
   */
  feedbackPanelTitle: string;
  /**
   * Placeholder text for the free-form notes textarea in the negative feedback
   * form.
   */
  feedbackDetailsPlaceholder: string;
  /** Label for the button that submits the negative feedback form. */
  feedbackSubmitButtonText: string;
  /** Label for the button that cancels/dismisses the negative feedback form. */
  feedbackCancelButtonText: string;
  /**
   * Tooltip/aria-label for the button that closes/cancels the negative feedback
   * form.
   */
  feedbackCloseButtonTitle: string;
  /** Label for the "Incorrect or incomplete" tag. */
  feedbackTagIncorrect: string;
  /** Label for the "Not what I asked for" tag. */
  feedbackTagNotWhatIAsked: string;
  /** Label for the "Slow or buggy" tag. */
  feedbackTagSlowOrBuggy: string;
  /** Label for the "Style or tone" tag. */
  feedbackTagStyleOrTone: string;
  /** Label for the "Safety or legal concern" tag. */
  feedbackTagSafetyOrLegal: string;
  /** Label for the "Other" tag. */
  feedbackTagOther: string;
}>;

type TagTranslationKey = Extract<
  keyof FeedbackActionsTranslations,
  `feedbackTag${string}`
>;

type FeedbackReasonOption = {
  value: AskAiFeedbackReason;
  translationKey: TagTranslationKey;
  defaultLabel: string;
};

// Hoisted at module level so the array identity is stable across renders.
const FEEDBACK_REASONS: FeedbackReasonOption[] = [
  {
    value: 'incorrect',
    translationKey: 'feedbackTagIncorrect',
    defaultLabel: 'Incorrect or incomplete',
  },
  {
    value: 'not_what_i_asked',
    translationKey: 'feedbackTagNotWhatIAsked',
    defaultLabel: 'Not what I asked for',
  },
  {
    value: 'slow_or_buggy',
    translationKey: 'feedbackTagSlowOrBuggy',
    defaultLabel: 'Slow or buggy',
  },
  {
    value: 'style_or_tone',
    translationKey: 'feedbackTagStyleOrTone',
    defaultLabel: 'Style or tone',
  },
  {
    value: 'safety_or_legal',
    translationKey: 'feedbackTagSafetyOrLegal',
    defaultLabel: 'Safety or legal concern',
  },
  {
    value: 'other',
    translationKey: 'feedbackTagOther',
    defaultLabel: 'Other',
  },
];

// Maximum number of characters allowed in the feedback notes field.
const MAX_NOTES_LENGTH = 1000;

type FeedbackView = 'actions' | 'note' | 'thanks';

interface FeedbackActionsProps {
  id: string;
  showActions: boolean;
  latestAssistantMessageContent: string | null;
  translations: FeedbackActionsTranslations;
  conversations: StoredSearchPlugin<StoredAskAiState>;
  onFeedback?: OnAskAiFeedback;
  /** When rendered in the Sidepanel the copy button is ordered first. */
  isSidepanel?: boolean;
}

export function FeedbackActions({
  id,
  showActions,
  latestAssistantMessageContent,
  translations,
  conversations,
  onFeedback,
  isSidepanel = false,
}: FeedbackActionsProps): JSX.Element | null {
  // Derive the initial view during render (no effect needed): if feedback was
  // already recorded for this message, jump straight to the "thanks" state.
  const [view, setView] = useState<FeedbackView>(() => {
    const message = conversations.getOne?.(id);
    return message?.feedback ? 'thanks' : 'actions';
  });
  const [tags, setTags] = useState<AskAiFeedbackReason[]>([]);
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [savingError, setSavingError] = useState<Error | null>(null);

  const {
    likeButtonTitle = 'Like',
    dislikeButtonTitle = 'Dislike',
    thanksForFeedbackText = 'Thanks for your feedback!',
  } = translations;

  const handleLike = async (): Promise<void> => {
    if (saving) return;
    setSavingError(null);
    setSaving(true);
    try {
      await onFeedback?.(id, { thumbs: 1 });
      setView('thanks');
    } catch (error) {
      setSavingError(error as Error);
    } finally {
      setSaving(false);
    }
  };

  const handleDislike = (): void => {
    setSavingError(null);
    setView('note');
  };

  const handleToggleTag = (value: AskAiFeedbackReason): void => {
    setTags((prev) =>
      prev.includes(value)
        ? prev.filter((tag) => tag !== value)
        : [...prev, value]
    );
  };

  const handleSubmitNote = async (): Promise<void> => {
    if (saving) return;
    setSavingError(null);
    setSaving(true);
    try {
      await onFeedback?.(id, {
        thumbs: 0,
        tags: tags.length > 0 ? tags : undefined,
        notes: notes.trim() || undefined,
      });
      setView('thanks');
    } catch (error) {
      setSavingError(error as Error);
    } finally {
      setSaving(false);
    }
  };

  const handleCloseNote = (): void => {
    setTags([]);
    setNotes('');
    setSavingError(null);
    setView('actions');
  };

  if (!showActions || !latestAssistantMessageContent) {
    return null;
  }

  const copyButton = (
    <CopyButton
      translations={translations}
      onClick={() =>
        navigator.clipboard.writeText(latestAssistantMessageContent)
      }
    />
  );

  // Feedback needs a backend to submit to; without `onFeedback` only the copy
  // button is rendered.
  const feedbackControls =
    view === 'thanks' ? (
      <p className="DocSearch-AskAiScreen-FeedbackText DocSearch-AskAiScreen-FeedbackText--visible">
        {thanksForFeedbackText}
      </p>
    ) : (
      <>
        {saving && view === 'actions' ? (
          <LoadingIcon className="DocSearch-AskAiScreen-SmallerLoadingIcon" />
        ) : (
          <>
            <LikeButton title={likeButtonTitle} onClick={handleLike} />
            <DislikeButton title={dislikeButtonTitle} onClick={handleDislike} />
          </>
        )}
        {savingError && view === 'actions' ? (
          <p className="DocSearch-AskAiScreen-FeedbackText">
            {savingError.message || 'An error occured'}
          </p>
        ) : null}
      </>
    );

  return (
    <>
      <div className="DocSearch-AskAiScreen-Actions-Controls">
        {isSidepanel ? copyButton : null}

        {onFeedback ? feedbackControls : null}

        {isSidepanel ? null : copyButton}
      </div>

      {view === 'note' ? (
        <NegativeFeedbackPanel
          translations={translations}
          tags={tags}
          notes={notes}
          saving={saving}
          savingError={savingError}
          onToggleTag={handleToggleTag}
          onNotesChange={setNotes}
          onSubmit={handleSubmitNote}
          onClose={handleCloseNote}
        />
      ) : null}
    </>
  );
}

interface NegativeFeedbackPanelProps {
  translations: FeedbackActionsTranslations;
  tags: AskAiFeedbackReason[];
  notes: string;
  saving: boolean;
  savingError: Error | null;
  onToggleTag: (tag: AskAiFeedbackReason) => void;
  onNotesChange: (notes: string) => void;
  onSubmit: () => void;
  onClose: () => void;
}

function NegativeFeedbackPanel({
  translations,
  tags,
  notes,
  saving,
  savingError,
  onToggleTag,
  onNotesChange,
  onSubmit,
  onClose,
}: NegativeFeedbackPanelProps): JSX.Element {
  const feedbackTitleId = React.useId();
  const {
    feedbackPanelTitle = 'What went wrong? (optional)',
    feedbackDetailsPlaceholder = 'Share some details...',
    feedbackSubmitButtonText = 'Submit',
    feedbackCancelButtonText = 'Cancel',
  } = translations;

  return (
    <div
      className="DocSearch-Feedback-Panel"
      role="group"
      aria-labelledby={feedbackTitleId}
    >
      <div className="DocSearch-Feedback-Panel-Header">
        <p className="DocSearch-Feedback-Panel-Title" id={feedbackTitleId}>
          {feedbackPanelTitle}
        </p>
      </div>

      <div className="DocSearch-Feedback-Panel-Reasons">
        {FEEDBACK_REASONS.map((reason) => {
          const isSelected = tags.includes(reason.value);
          return (
            <button
              key={reason.value}
              type="button"
              className="DocSearch-Feedback-Panel-Reason"
              aria-pressed={isSelected}
              onClick={() => onToggleTag(reason.value)}
            >
              <span>
                {translations[reason.translationKey] ?? reason.defaultLabel}
              </span>
            </button>
          );
        })}
      </div>

      <textarea
        className="DocSearch-Feedback-Panel-Textarea"
        placeholder={feedbackDetailsPlaceholder}
        value={notes}
        rows={3}
        maxLength={MAX_NOTES_LENGTH}
        onChange={(event) =>
          onNotesChange(event.target.value.slice(0, MAX_NOTES_LENGTH))
        }
      />

      <p className="DocSearch-Feedback-Panel-CharCount" aria-live="polite">
        {notes.length}/{MAX_NOTES_LENGTH}
      </p>

      {savingError ? (
        <p className="DocSearch-Feedback-Panel-Error">
          {savingError.message || 'An error occured'}
        </p>
      ) : null}

      <div className="DocSearch-Feedback-Panel-Actions">
        <button
          type="button"
          className="DocSearch-Feedback-Panel-Cancel"
          onClick={onClose}
        >
          {feedbackCancelButtonText}
        </button>
        <button
          type="button"
          className="DocSearch-Feedback-Panel-Submit"
          disabled={saving}
          onClick={onSubmit}
        >
          {saving ? (
            <LoadingIcon className="DocSearch-AskAiScreen-SmallerLoadingIcon" />
          ) : (
            feedbackSubmitButtonText
          )}
        </button>
      </div>
    </div>
  );
}

export function CopyButton({
  onClick,
  translations,
}: {
  onClick: () => void;
  translations: FeedbackActionsTranslations;
}): JSX.Element {
  const { copyButtonTitle = 'Copy', copyButtonCopiedText = 'Copied!' } =
    translations;

  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    if (isCopied) {
      const timer = setTimeout(() => {
        setIsCopied(false);
      }, 1500); // reset after 1.5 seconds
      return (): void => clearTimeout(timer);
    }
    return undefined;
  }, [isCopied]);

  const handleClick = (): void => {
    onClick();
    setIsCopied(true);
  };

  return (
    <button
      type="button"
      className={`DocSearch-AskAiScreen-ActionButton DocSearch-AskAiScreen-CopyButton ${
        isCopied ? 'DocSearch-AskAiScreen-CopyButton--copied' : ''
      }`}
      disabled={isCopied} // disable button briefly after copy
      title={isCopied ? copyButtonCopiedText : copyButtonTitle}
      onClick={handleClick}
    >
      {isCopied ? (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M20 6 9 17l-5-5" />
        </svg>
      ) : (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <rect width="14" height="14" x="8" y="8" rx="2" ry="2" />
          <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" />
        </svg>
      )}
    </button>
  );
}

